import sys

def count_words(s: str) -> int:
    n = len(s)
    i = 0
    cnt = 0
    while i < n:
        # skip any spaces
        while i < n and s[i] == ' ':
            i += 1
        if i >= n:
            break
        # a word starts here
        cnt += 1
        # skip the word characters
        while i < n and s[i] != ' ':
            i += 1
    return cnt

def main() -> None:
    line = sys.stdin.readline()
    # If the input is empty (e.g., EOF), treat as 0 words
    if not line:
        print(0)
        return
    print(count_words(line))

if __name__ == "__main__":
    main()
